/* APG-M10 prototype screens. Reads window.APG_VIEWS (generated by tools/build_m10_views.py from the APG code run on synthetic Builder Zero data) and draws six screens.
   It computes no amount: it formats the amounts the data carries and links each one to its evidence entry. It sends nothing anywhere: there is no network call in this file. */
(function () {
  'use strict';
  var M = window.APG_VIEWS;
  var SCREENS = [['portfolio', 'Portfolio'], ['project', 'Projects'], ['health', 'Data health'], ['imports', 'Imports'], ['approvals', 'Approvals'], ['materials', 'Materials']];
  var FIGCOLS = [['recognised_margin', 'Recognised margin'], ['forecast_final_margin', 'Forecast final margin'], ['cost_to_complete', 'Cost to complete'],
                 ['cash_adjusted_margin', 'Cash-adjusted margin'], ['retention_withheld', 'Retention withheld']];
  var STATE_WORDS = { authoritative: 'Authoritative', provisional: 'Provisional', cannot_assess: 'Cannot assess' };
  var LABEL_WORDS = { estimate: 'estimate', scenario: 'scenario', range: 'range', record: 'record', figure: 'calculated' };
  var ROUTE_WORDS = { action: 'Action', investigate: 'Investigate first', in_hand: 'In hand', close: 'Close', excluded: 'Excluded' };
  var V = null, lastFocus = null;

  function esc(s) { return String(s === null || s === undefined ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function words(t) { t = String(t || '').replace(/_/g, ' '); return t.charAt(0).toUpperCase() + t.slice(1); }
  var AUD0 = new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD', maximumFractionDigits: 0, minimumFractionDigits: 0 });
  var AUD2 = new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD', maximumFractionDigits: 2, minimumFractionDigits: 2 });
  var INT = new Intl.NumberFormat('en-AU');
  function dollars(c) { return AUD0.format(Math.round(c / 100)); }
  function exact(c) { return AUD2.format(c / 100); }
  function day(d) { if (!d) return ''; var p = String(d).slice(0, 10).split('-'); var m = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'][+p[1] - 1]; return (+p[2]) + ' ' + m + ' ' + p[0]; }

  /* One amount. n = {cents, state?, label?, ev}. A missing value is never drawn as zero. */
  function num(n, what, opts) {
    opts = opts || {};
    if (!n) return '<span class="muted">Not recorded</span>';
    var st = n.state || '', lb = n.label || '', ev = n.ev ? ' data-ev="' + esc(n.ev) + '"' : '';
    var count = lb === 'count';
    var aria = what ? esc(what) + ': ' : '';
    if (n.cents === null || n.cents === undefined) {
      if (st === 'cannot_assess') {
        return '<button type="button" class="num cannot_assess" data-state="cannot_assess"' + ev + ' aria-label="' + aria + 'cannot assess. Open the evidence and reasons">' +
               '<span class="void"><span>Cannot assess</span></span></button>';
      }
      var t = lb === 'none' ? 'No defensible amount' : 'No amount';
      return '<button type="button" class="num none" data-state="none"' + ev + ' aria-label="' + aria + t.toLowerCase() + '. Open the evidence"><span class="void">' + t + '</span></button>';
    }
    var shown = count ? INT.format(n.cents) : dollars(n.cents);
    var mark = '';
    if (st === 'provisional') mark = '<span class="mark">provisional</span>';
    else if (lb === 'estimate' || lb === 'scenario' || lb === 'range') mark = '<span class="mark est">' + LABEL_WORDS[lb] + '</span>';
    if (opts.nomark) mark = '';
    var label = aria + shown + (st ? ', ' + (STATE_WORDS[st] || st).toLowerCase() : '') + (lb && !count && lb !== 'figure' && lb !== 'record' ? ', ' + LABEL_WORDS[lb] : '') + '. Open the evidence';
    return '<button type="button" class="num ' + esc(st) + '" data-state="' + esc(st || 'unstated') + '" data-label="' + esc(lb) + '" data-cents="' + esc(n.cents) + '"' + ev +
           ' aria-label="' + esc(label) + '">' + esc(shown) + mark + '</button>';
  }
  /* The amount repeated in a collapsed row's summary: plain text, because a summary may not hold a button; the same amount is an evidence button inside the row. */
  function amountText(n) {
    if (!n || n.cents === null || n.cents === undefined) return '<span class="muted small">' + (n && n.state === 'cannot_assess' ? 'Cannot assess' : 'No defensible amount') + '</span>';
    return '<span class="sum-amt">' + esc(dollars(n.cents)) + (n.state === 'provisional' ? ' <span class="tag waiting">provisional</span>' : (n.label === 'estimate' ? ' <span class="tag">estimate</span>' : '')) + '</span>';
  }
  function reasons(list) {
    if (!list || !list.length) return '';
    return '<ul>' + list.map(function (r) { return '<li>' + esc(r.plain || 'Recorded as') + ' <span class="code">' + esc(r.code) + '</span></li>'; }).join('') + '</ul>';
  }
  function tag(text, cls) { return '<span class="tag ' + (cls || '') + '">' + esc(text) + '</span>'; }

  /* ---------------------------------------------------------------- routing ---------------------------------------------------------------- */
  function route() {
    var h = (location.hash || '').replace(/^#\/?/, '').split('/');
    var view = M.views[h[0]] ? h[0] : M.meta.order[0];
    var screen = SCREENS.some(function (s) { return s[0] === h[1]; }) ? h[1] : 'portfolio';
    return { view: view, screen: screen, arg: h[2] ? decodeURIComponent(h[2]) : null };
  }
  function href(screen, arg, view) { return '#/' + (view || V.view) + '/' + screen + (arg ? '/' + encodeURIComponent(arg) : ''); }

  function render() {
    var r = route();
    V = M.views[r.view];
    drawTitle(r); drawIndex(r);
    var main = document.getElementById('main');
    var fn = { portfolio: portfolio, project: project, health: health, imports: imports, approvals: approvals, materials: materials }[r.screen];
    main.innerHTML = '<div class="screen" data-screen="' + r.screen + '">' + fn(r.arg) + statement() + '</div>';
    document.title = SCREENS.filter(function (s) { return s[0] === r.screen; })[0][1] + ', Profit Guardian Prototype';
  }

  function drawTitle(r) {
    var opts = M.meta.order.map(function (k) { return '<option value="' + esc(k) + '"' + (k === r.view ? ' selected' : '') + '>' + esc(M.meta.labels[k]) + '</option>'; }).join('');
    document.getElementById('titleblock').innerHTML =
      '<div class="brand">Profit Guardian<small>Prototype, synthetic data</small></div>' +
      '<div><span class="tb-k">Builder</span><span class="tb-v">' + esc(V.builder) + '</span></div>' +
      '<div><label class="tb-k" for="viewas">Viewing as</label><select id="viewas">' + opts + '</select></div>' +
      '<div><span class="tb-k">Data as of</span><span class="tb-v">' + esc(day(V.as_of)) + '</span></div>' +
      '<div><span class="tb-k">Status</span><span class="tb-v tb-proto">Not production; nothing is sent</span></div>' +
      '<div><span class="tb-k">Amounts</span><span class="tb-v">Whole dollars; cents in the evidence</span></div>';
    document.getElementById('viewas').addEventListener('change', function (e) { location.hash = '#/' + e.target.value + '/' + route().screen; });
  }

  function waiting() { return V.approvals.filter(function (a) { return a.present.can_approve; }).length; }
  function drawIndex(r) {
    var w = waiting();
    document.getElementById('index').innerHTML = '<ol>' + SCREENS.map(function (s) {
      var c = s[0] === 'approvals' && w ? '<span class="count">' + w + ' waiting</span>' : '';
      return '<li><a href="' + href(s[0]) + '"' + (s[0] === r.screen ? ' aria-current="page"' : '') + '>' + esc(s[1]) + c + '</a></li>';
    }).join('') + '</ol>' +
    '<div class="index-foot"><p>' + esc(V.person.name) + '</p><p>Sees ' + (V.access.tenant_level ? 'the whole builder' : 'only ' + esc(V.access.projects.join(', '))) +
    '; can approve ' + (V.access.approve.length ? esc(V.access.approve.join(', ')) : 'nothing') + '.</p>' +
    '<label class="theme small" for="theme">Theme</label><select id="theme"><option value="">Match the device</option><option value="light">Light</option><option value="dark">Dark</option></select></div>';
    var t = document.getElementById('theme');
    t.value = document.documentElement.getAttribute('data-theme') || '';
    t.addEventListener('change', function () { if (t.value) document.documentElement.setAttribute('data-theme', t.value); else document.documentElement.removeAttribute('data-theme'); try { localStorage.setItem('apg-theme', t.value); } catch (e) {} });
  }
  function statement() { return '<footer class="statement">' + esc(M.meta.statement) + ' Release: ' + esc(M.meta.release) + '.</footer>'; }
  function noAccess(what) { return '<h1>' + esc(what) + '</h1><p class="lede">' + esc(V.person.name) + ' has no builder-wide access, so this screen is not shown. ' +
                                    'Access comes from the project-action port of the M9 contract; nothing here is hidden by the screen alone.</p>'; }

  /* ---------------------------------------------------------------- portfolio ---------------------------------------------------------------- */
  function portfolio() {
    var st = V.figure_states, a = (st.authoritative || []).length, p = (st.provisional || []).length, c = (st.cannot_assess || []).length, n = a + p + c;
    var head = p || c ? (p ? p + ' of ' + n + (p === 1 ? ' figures is provisional' : ' figures are provisional') : '') + (p && c ? ', and ' : '') + (c ? c + (c === 1 ? ' cannot' : ' cannot') + ' be assessed' : '') + '.' :
                       'All ' + n + ' figures are authoritative.';
    head = head.charAt(0).toUpperCase() + head.slice(1);
    var cells = [];
    V.projects.forEach(function (pr) { cells.push('<span class="grp">' + Object.keys(pr.figures).sort().map(function (k) { return '<i class="' + esc(pr.figures[k].state) + '"></i>'; }).join('') + '</span>'); });
    var rows = V.projects.map(function (pr) {
      return '<tr><th scope="row"><a href="' + href('project', pr.id) + '">' + esc(pr.name) + '</a><div class="code">' + esc(pr.id) + '</div></th>' +
        '<td class="r">' + num(pr.contract_value, 'Contract value, ' + pr.id) + '</td>' +
        FIGCOLS.map(function (f) { var fg = pr.figures[f[0]]; return '<td class="r">' + (fg ? num(fg, f[1] + ', ' + pr.id) : '<span class="muted">Not calculated</span>') + '</td>'; }).join('') +
        '<td class="r"><a href="' + href('project', pr.id) + '">' + pr.findings.length + '</a></td></tr>';
    }).join('');
    var ex = V.exposure.map(function (e) {
      var two = e.available && e.upper.cents !== e.lower.cents;
      var range = e.available ? num(e.lower, 'Lower end, ' + words(e.interpretation), { nomark: two }) + (two ? ' to ' + num(e.upper, 'Upper end, ' + words(e.interpretation), { nomark: true }) + ' <span class="tag">range</span>' : '') :
                                num({ cents: null, label: 'none', ev: e.ev }, words(e.interpretation));
      return '<tr><th scope="row">' + esc(words(e.interpretation)) + '</th><td class="r">' + e.findings + '</td><td class="r">' + range + '</td><td class="r">' + (e.unquantified || 0) + '</td></tr>';
    }).join('');
    var w = waiting();
    var out = '<h1>' + esc(head) + '</h1>' +
      '<p class="lede">' + V.projects.length + (V.projects.length === 1 ? ' project' : ' projects') + ' as of ' + esc(day(V.as_of)) + '. Each figure is shown as APG calculated it and nothing is added up across projects: APG has no portfolio-level figure, and these figures stand on different footings.</p>' +
      (V.data_health && V.data_health.connected_route.status !== 'can_assess' ? '<p class="note prov">These figures come from the file-import route. The connected-systems route cannot assess this builder yet: ' +
        V.data_health.connected_route.reasons.length + ' reasons, listed on <a href="' + href('health') + '">Data health</a>.</p>' : '') +
      '<div class="strip" aria-hidden="true">' + cells.join('') + '</div>' +
      '<ul class="legend"><li>' + a + ' authoritative</li><li class="provisional">' + p + ' provisional</li><li class="cannot_assess">' + c + ' cannot be assessed</li></ul>' +
      '<section aria-labelledby="h-ledger"><header><h2 id="h-ledger">Projects</h2><span class="muted small">Select any amount to see how it was worked out</span></header>' +
      '<div class="table-wrap"><table><thead><tr><th scope="col">Project</th><th scope="col" class="r">Contract value</th>' +
      FIGCOLS.map(function (f) { return '<th scope="col" class="r">' + esc(f[1]) + '</th>'; }).join('') + '<th scope="col" class="r">Findings</th></tr></thead><tbody>' + rows +
      '</tbody><tfoot><tr><td colspan="' + (FIGCOLS.length + 3) + '">No totals. A total would mix authoritative, provisional and unassessable figures, and APG calculates none.</td></tr></tfoot></table></div></section>';
    out += '<section aria-labelledby="h-exp"><header><h2 id="h-exp">Exposure found by detection</h2><span class="muted small">A range per kind of exposure, never one total</span></header>' +
      (ex ? '<div class="table-wrap"><table><thead><tr><th scope="col">Kind</th><th scope="col" class="r">Findings</th><th scope="col" class="r">Range of quantified amounts</th><th scope="col" class="r">Not quantified</th></tr></thead><tbody>' + ex +
      '</tbody><caption>Amounts inside one group of related findings may include each other, so the range is not a sum. A finding without an amount is not zero exposure.</caption></table></div>' :
      (V.findings.length ? '<p class="muted">None of the ' + V.findings.length + (V.findings.length === 1 ? ' finding' : ' findings') + ' visible here is a financial exposure. See <a href="' + href('project') + '">Projects</a>.</p>' :
                           '<p class="muted">No findings are visible to this person.</p>')) + '</section>';
    out += '<section aria-labelledby="h-you"><header><h2 id="h-you">Waiting for you</h2></header>' +
      (w ? '<p><a href="' + href('approvals') + '">' + w + (w === 1 ? ' proposed action needs' : ' proposed actions need') + ' your approval</a>.</p>' : '<p class="muted">Nothing is waiting for your approval.</p>') + '</section>';
    if (V.workflow.length || V.policies.length) {
      out += '<section aria-labelledby="h-prep"><details><summary><h2 id="h-prep" style="display:inline">How this demonstration data was prepared</h2></summary>' +
        '<p class="note">Synthetic people moved the findings along so every screen has something to show, as the M7 golden runs do. None of this is a real decision.</p><ul>' +
        V.workflow.map(function (x) { return '<li>' + esc(x.who) + ': ' + esc(x.what) + '</li>'; }).join('') + '</ul><p>Policies used (all illustrative, synthetic values):</p><ul>' +
        V.policies.map(function (x) { return '<li>' + esc(x.name) + ' ' + esc(x.version) + ': ' + (x.approved ? 'approved by its synthetic owner' : 'not approved') + '</li>'; }).join('') +
        '</ul><p class="muted small">The construction definitions behind these figures are PROPOSED, not locked.</p></details></section>';
    }
    return out;
  }

  /* ---------------------------------------------------------------- project ---------------------------------------------------------------- */
  var CELLS = [['forecast_final_margin', true], ['recognised_margin', true], ['cash_adjusted_margin', true], ['cost_to_complete', false], ['secured_revenue', false], ['actual_cost', false],
               ['commitments', false], ['retention_withheld', false], ['security', false], ['retention_carrying', false]];
  function project(arg) {
    var tenantTab = V.access.tenant_level;
    var ids = V.projects.map(function (p) { return p.id; });
    var cur = arg === 'builder' && tenantTab ? 'builder' : (ids.indexOf(arg) >= 0 ? arg : ids[0]);
    var tabs = '<nav class="tabs" aria-label="Projects">' + V.projects.map(function (p) {
      return '<a href="' + href('project', p.id) + '"' + (p.id === cur ? ' aria-current="page"' : '') + '>' + esc(p.name) + '</a>';
    }).join('') + (tenantTab ? '<a href="' + href('project', 'builder') + '"' + (cur === 'builder' ? ' aria-current="page"' : '') + '>Builder-wide</a>' : '') + '</nav>';
    if (cur === 'builder') {
      var tf = V.findings.filter(function (f) { return f.level === 'tenant'; });
      return '<h1>Builder-wide findings</h1><p class="lede">Findings about the builder as a whole, not one project: suppliers, quotes and records shared across projects.</p>' + tabs + findingsBlock(tf);
    }
    var pr = V.projects.filter(function (p) { return p.id === cur; })[0];
    if (!pr) return '<h1>Projects</h1><p class="lede">No project is visible to this person.</p>';
    var pc = pr.percent_complete_bps !== null && pr.percent_complete_bps !== undefined ? (pr.percent_complete_bps / 100).toFixed(2) + '% complete (cost to cost)' : '';
    var cells = CELLS.filter(function (c) { return pr.figures[c[0]]; }).map(function (c) {
      var fg = pr.figures[c[0]];
      return '<div class="cell' + (c[1] ? ' key' : '') + '"><span class="k">' + esc(fg.title) + '</span><span class="v">' + num(fg, fg.title + ', ' + pr.id) + '</span>' +
             '<span class="small muted">' + esc(STATE_WORDS[fg.state] || fg.state) + '</span>' + reasons(fg.reasons) + '</div>';
    }).join('');
    var fs = V.findings.filter(function (f) { return f.project === pr.id; });
    var recs = V.recommendations.filter(function (r) { return fs.some(function (f) { return f.id === r.finding_id; }); });
    return '<h1>' + esc(pr.name) + '</h1><p class="lede">' + esc(pr.id) + '. Contract value ' + num(pr.contract_value, 'Contract value, ' + pr.id) + '. ' + esc(pc) +
           (pr.start ? '. Started ' + esc(day(pr.start)) + ', planned finish ' + esc(day(pr.planned_finish)) : '') + '.</p>' + tabs +
           '<section aria-labelledby="h-fig" style="margin-top:24px"><header><h2 id="h-fig">Figures</h2><span class="muted small">As calculated by APG, with the reasons it gave</span></header><div class="cells">' + cells + '</div></section>' +
           '<section id="findings" aria-labelledby="h-fnd"><header><h2 id="h-fnd">Findings</h2><span class="muted small">' + fs.length + ' found by the detection rules</span></header>' + findingsBlock(fs) + '</section>' +
           '<section aria-labelledby="h-rec"><header><h2 id="h-rec">Recommendations</h2><span class="muted small">Estimates and next steps, never savings</span></header>' + recBlock(recs) + '</section>';
  }
  function findingsBlock(fs) {
    if (!fs.length) return '<p class="muted">No findings.</p>';
    return '<ul class="entries">' + fs.map(function (f) {
      var recs = f.records.map(function (e) { return '<li><button type="button" class="num" data-ev="' + esc(e) + '" aria-label="Source record ' + esc(e.replace('E-rec-', '')) + '. Open it">' + esc(e.replace('E-rec-', '')) + '</button></li>'; }).join('');
      return '<li class="entry" data-finding="' + esc(f.id) + '"><details><summary><span><span class="chev"></span><span class="title">' + esc(f.kind) + '</span> ' + tag(words(f.status)) +
        '<br><span class="meta">' + esc(f.subject) + ', ' + esc(words(f.interpretation)) + ', evidence ' + esc(f.evidence_strength || 'not rated') + '</span></span>' +
        '<span class="r">' + amountText(f.amount) + '</span></summary><div class="body"><dl><dt>Amount</dt><dd>' + num(f.amount, f.kind + ' on ' + f.subject) + (f.amount && f.amount.label && f.amount.label !== 'none' ? ' <span class="small muted">' + esc(f.amount.label === 'record' ? 'taken from a source record' : f.amount.label === 'figure' ? 'from a stored APG calculation' : 'an estimate resting on an assumption') + '</span>' : '') + '</dd>' +
        '<dt>Observed</dt><dd>' + esc(f.observed) + '</dd><dt>Expected</dt><dd>' + esc(f.expected) + '</dd><dt>Why it matters</dt><dd>' + esc(f.why) + '</dd>' +
        (f.amount_basis ? '<dt>Amount basis</dt><dd>' + esc(f.amount_basis) + '</dd>' : '') +
        (f.missing_information && f.missing_information.length ? '<dt>Missing</dt><dd>' + esc(f.missing_information.join('; ')) + '</dd>' : '') +
        '<dt>Source records</dt><dd><ul class="small" style="margin:0;padding-left:1.1em">' + recs + '</ul></dd><dt>Finding</dt><dd><button type="button" class="num" data-ev="' + esc(f.ev) + '" aria-label="Finding ' + esc(f.id) + '. Open its record">' + esc(f.id) + '</button> ' +
        '<span class="code">rule ' + esc(f.rule) + ', version ' + esc(f.version) + '</span></dd></dl></div></details></li>';
    }).join('') + '</ul>';
  }
  function recBlock(recs) {
    if (!recs.length) return '<p class="muted">No recommendations.</p>';
    return '<p class="note">' + esc(V.recommendation_statement) + '</p><div class="table-wrap"><table><thead><tr><th scope="col">Recommendation</th><th scope="col">Next step</th><th scope="col" class="r">Potential gross amount</th><th scope="col" class="r">Estimated net benefit</th><th scope="col">Why not yet an action</th></tr></thead><tbody>' +
      recs.map(function (r) {
        var f = V.findings.filter(function (x) { return x.id === r.finding_id; })[0] || {};
        var codes = r.codes.length ? r.codes.map(function (c) { return esc(c.plain || c.code) + ' <span class="code">' + esc(c.code) + '</span>'; }).join('<br>') : (r.blocked_by.length ? esc(r.blocked_by.join('; ')) : '<span class="muted">Nothing blocks it; approval by the ' + esc(r.approval_role || 'named role') + '</span>');
        return '<tr data-rec="' + esc(r.id) + '"><th scope="row">' + esc(f.kind || r.finding_id) + '<div class="code">' + esc(r.id) + '</div></th><td>' + tag(ROUTE_WORDS[r.route] || r.route, r.route === 'action' ? 'action' : '') +
          (r.category ? '<div class="small muted">' + esc(words(r.category)) + '</div>' : '') + '</td><td class="r">' + num(r.potential_gross, 'Potential gross amount, ' + r.id) + '</td><td class="r">' +
          (r.net_status === 'estimated' ? num(r.estimated_net, 'Estimated net benefit, ' + r.id) : '<span class="muted small">Not estimated: the owner has not entered the benefit and every cost</span>') + '</td><td class="small">' + codes + '</td></tr>';
      }).join('') + '</tbody><caption>A potential gross amount is the size of the exposure or opportunity, not a benefit. No amount here is realised: that needs an approved baseline, implementation evidence and an authorised verification.</caption></table></div>';
  }

  /* ---------------------------------------------------------------- data health ---------------------------------------------------------------- */
  function verdict(g) {
    return g.status === 'can_assess' ? '<p class="verdict">Can assess</p>' : '<p class="verdict cannot_assess"><span>Cannot assess</span></p>';
  }
  function health() {
    var h = V.data_health;
    if (!h) return noAccess('Data health');
    var fr = h.file_route, cr = h.connected_route;
    var crReasons = cr.reasons.length ? '<div class="table-wrap"><table><thead><tr><th scope="col">Reason</th><th scope="col">Where</th><th scope="col">Detail</th></tr></thead><tbody>' + cr.reasons.map(function (r) {
      return '<tr><td>' + esc(r.plain || words(r.code)) + '<div class="code">' + esc(r.code) + '</div></td><td class="small">' + esc(r.scope) + '</td><td class="small">' + esc(r.detail) + '</td></tr>'; }).join('') + '</tbody></table></div>' : '';
    var empty = cr.reasons.filter(function (r) { return r.code === 'SOURCE_EMPTY'; }).length;
    var head = cr.status === 'can_assess' && fr.gate.status === 'can_assess' ? 'Both import routes can be assessed.' :
               (fr.gate.status === 'can_assess' ? 'The file route can be assessed. The connected-systems route cannot.' : 'This data cannot be assessed.');
    var out = '<h1>' + esc(head) + '</h1><p class="lede">Whether APG may assess at all, before any figure is trusted. A route that cannot be assessed shows its reasons, never an old or partial figure.</p>' +
      '<div class="route-card"><div><h2>' + esc(fr.name) + '</h2>' + verdict(fr.gate) + '<p class="small">The figures on these screens come from this route, where every APG engine runs.</p>' + reasons(fr.gate.reasons) + '</div>' +
      '<div><h2>' + esc(cr.name) + '</h2>' + verdict(cr) + (cr.status === 'can_assess' ? '<p class="small">Every expected record type arrived and was applied with no reason.</p>' :
        '<p class="small">' + (empty ? empty + ' record types arrived empty. Whether some record types may validly be empty is an open owner decision (CF-53), so for now an empty delivery stops the assessment.' : 'See the reasons below.') + '</p>') + '</div></div>' +
      (crReasons ? '<section aria-labelledby="h-crr"><header><h2 id="h-crr">Why the connected-systems route cannot be assessed</h2></header>' + crReasons + '</section>' : '');
    out += '<section aria-labelledby="h-src"><header><h2 id="h-src">Sources</h2><span class="muted small">File route, as received</span></header><div class="table-wrap"><table><thead><tr><th scope="col">Source</th><th scope="col">State</th><th scope="col">Last received</th><th scope="col" class="r">Files</th><th scope="col" class="r">Rows</th><th scope="col" class="r">Rejected rows</th></tr></thead><tbody>' +
      fr.sources.map(function (s) { var ev = s.ev[0]; return '<tr><th scope="row">' + esc(words(s.source)) + '</th><td>' + esc(words(s.state)) + '</td><td>' + esc(day(s.last_receipt)) + '</td><td class="r">' + s.files + '</td><td class="r">' +
        num({ cents: s.rows, label: 'count', ev: ev }, 'Rows from ' + s.source) + '</td><td class="r">' + num({ cents: s.rejected_rows, label: 'count', ev: ev }, 'Rejected rows from ' + s.source) + '</td></tr>'; }).join('') +
      '</tbody><caption>Rejected rows would be shown next to the figures they would have changed (F-19). There are none in this synthetic data.</caption></table></div></section>';
    var keys = ['accepted', 'accepted_with_warnings', 'pending_reconciliation', 'quarantined', 'duplicate_delivery', 'rejected_rows'];
    out += '<section aria-labelledby="h-q"><header><h2 id="h-q">Record outcomes</h2><span class="muted small">What happened to each record after it arrived</span></header><div class="table-wrap"><table><thead><tr><th scope="col">Record type</th>' +
      keys.map(function (k) { return '<th scope="col" class="r">' + esc(words(k)) + '</th>'; }).join('') + '</tr></thead><tbody>' +
      fr.quality.map(function (q) { return '<tr><th scope="row">' + esc(words(q.kind)) + '</th>' + keys.map(function (k) { return '<td class="r">' + (q.counts[k] ? num(q.counts[k], words(k) + ', ' + q.kind) : '<span class="muted">-</span>') + '</td>'; }).join('') + '</tr>'; }).join('') +
      '</tbody></table></div></section>';
    out += '<section aria-labelledby="h-held"><header><h2 id="h-held">Records held back or flagged</h2><span class="muted small">' + fr.held.length + ' records; each figure lists the ones it left out</span></header><div class="table-wrap"><table><thead><tr><th scope="col">Record</th><th scope="col">Status</th><th scope="col">Why</th><th scope="col" class="r">Amount</th></tr></thead><tbody>' +
      fr.held.map(function (x) { return '<tr><th scope="row">' + esc(x.ref) + '</th><td>' + esc(words(x.status)) + '</td><td class="small">' + (x.codes.length ? x.codes.map(function (c) { return esc(c.plain || 'Recorded as') + ' <span class="code">' + esc(c.code) + '</span>'; }).join('<br>') : '<span class="muted">Warnings only</span>') +
        '</td><td class="r">' + num(x.amount, 'Amount, ' + x.ref) + '</td></tr>'; }).join('') + '</tbody></table></div></section>';
    return out;
  }

  /* ---------------------------------------------------------------- imports ---------------------------------------------------------------- */
  function imports() {
    var h = V.data_health;
    if (!h) return noAccess('Imports');
    var fr = h.file_route, cr = h.connected_route;
    var cols = [['rows', 'Rows'], ['new', 'New'], ['revision', 'Revised'], ['duplicate', 'Duplicate'], ['conflict', 'Conflict'], ['held_at_intake', 'Held'], ['rejected', 'Rejected']];
    var held = fr.receipts.reduce(function (s, r) { return s + (r.held_at_intake.cents || 0); }, 0);
    var out = '<h1>' + fr.receipts.length + ' files imported, none rejected.</h1><p class="lede">The last import of each file on the file route, with what happened to its rows. Select a count to see the receipt.</p>' +
      '<section aria-labelledby="h-rc" style="margin-top:24px"><div class="table-wrap"><table><thead><tr><th scope="col">File</th><th scope="col">Record type</th><th scope="col">Source</th>' +
      cols.map(function (c) { return '<th scope="col" class="r">' + c[1] + '</th>'; }).join('') + '</tr></thead><tbody>' +
      fr.receipts.map(function (r) { return '<tr><th scope="row" id="h-rc">' + esc(r.file) + '</th><td>' + esc(words(r.entity)) + '</td><td class="small">' + esc(words(r.source)) + '</td>' +
        cols.map(function (c) { return '<td class="r">' + num(r[c[0]], c[1] + ' rows, ' + r.file) + '</td>'; }).join('') + '</tr>'; }).join('') + '</tbody></table></div></section>';
    out += '<section aria-labelledby="h-qq"><header><h2 id="h-qq">Values waiting for a person</h2><span class="muted small">' + fr.quarantine.length + ' held because two systems disagree</span></header>' +
      (fr.quarantine.length ? '<div class="table-wrap"><table><thead><tr><th scope="col">Value</th><th scope="col">Systems disagree</th><th scope="col">Who resolves it</th><th scope="col">Status</th></tr></thead><tbody>' +
      fr.quarantine.map(function (q) { return '<tr><th scope="row"><button type="button" class="num" data-ev="' + esc(q.ev) + '" aria-label="Held value ' + esc(q.key) + '. Open it">' + esc(q.key) + '</button></th><td class="small">' +
        (q.candidates || []).map(function (c) { return esc(words(c[0])) + ': ' + esc(c[1]); }).join('<br>') + '</td><td>' + esc(words(q.resolver_role)) + '</td><td>' + esc(words(q.status)) + '</td></tr>'; }).join('') + '</tbody></table></div>' : '<p class="muted">None.</p>') + '</section>';
    out += '<section aria-labelledby="h-ci"><header><h2 id="h-ci">' + esc(cr.name) + '</h2><span class="muted small">Imports through AUIF rev14 into a separate synthetic world</span></header><div class="table-wrap"><table><thead><tr><th scope="col">Record type</th><th scope="col">Integration</th><th scope="col">Result</th><th scope="col">Reasons</th></tr></thead><tbody>' +
      cr.imports.map(function (i) { return '<tr><th scope="row">' + esc(words(i.record_type)) + '</th><td class="small">' + esc(i.integration) + '</td><td>' + (i.status === 'applied' ? tag('Applied', 'done') : tag(words(i.status), 'waiting')) + '</td><td class="small">' +
        (i.reasons.length ? i.reasons.map(function (r) { return esc(r.plain || words(r.code)) + ' <span class="code">' + esc(r.code) + '</span>'; }).join('<br>') : '<span class="muted">None</span>') + '</td></tr>'; }).join('') + '</tbody></table></div></section>';
    return out;
  }

  /* ---------------------------------------------------------------- approvals ---------------------------------------------------------------- */
  function approvals() {
    var w = waiting();
    var head = V.approvals.length ? (w ? w + (w === 1 ? ' proposed action is' : ' proposed actions are') + ' waiting for your approval.' : 'Nothing is waiting for your approval.') : 'No proposed actions are visible to you.';
    var out = '<h1>' + esc(head) + '</h1><p class="lede">Each approval covers one exact version of a finding, its evidence and the proposal you were shown. If any of them changes, the approval ends and a new one is needed.</p>' +
      '<p class="note prov">Prototype: approving here sends nothing. The screen shows the exact request the product would send to the approval boundary.</p>';
    out += '<ul class="entries" style="margin-top:24px">' + V.approvals.map(function (a, i) {
      var f = a.finding || {}, pr = a.present.proposal || {};
      var state = a.approved ? tag('Approved', 'done') : (a.present.can_approve ? tag('Waiting for you', 'waiting') : tag('View only'));
      var body = '<dl><dt>Proposed action</dt><dd>' + esc(pr.text) + '</dd><dt>Proposed by</dt><dd>' + esc(pr.proposed_by) + ', ' + esc(day(pr.proposed_at)) + '</dd>' +
        '<dt>Finding</dt><dd>' + esc(f.observed || '') + '</dd><dt>Amount</dt><dd>' + num(f.amount, 'Amount, ' + (f.subject || '')) + '</dd>' +
        '<dt>Evidence</dt><dd><button type="button" class="num" data-ev="' + esc(f.ev) + '" aria-label="Finding ' + esc(a.finding_id) + '. Open its record">' + esc(a.finding_id) + '</button></dd></dl>';
      if (a.approved) {
        var ok = a.in_force && a.in_force.valid;
        body += '<p>Approved by ' + esc(a.approved.approved_by) + ' on ' + esc(day(a.approved.approved_at)) + ' for version ' + esc(a.approved.approved_version) + '. ' +
          (ok ? 'Still in force for exactly this version, evidence and proposal.' : 'No longer in force.') + ' <span class="code">check_for_execution: ' + esc(a.in_force ? a.in_force.code : 'not checked') + '</span></p>';
      } else if (a.present.can_approve && a.request) {
        var rq = a.request;
        body += '<form class="approve" data-i="' + i + '" novalidate><p class="small">This approval covers exactly:</p><dl class="req"><dt>Finding version</dt><dd data-k="version">' + esc(rq.version) + '</dd>' +
          '<dt>Evidence digest</dt><dd data-k="digest" class="code">' + esc(rq.digest) + '</dd><dt>Proposal</dt><dd data-k="proposal" class="code">' + esc(rq.proposal) + '</dd></dl>' +
          '<label for="why-' + i + '">Why you approve it</label><textarea id="why-' + i + '" required aria-describedby="why-help-' + i + '"></textarea><p id="why-help-' + i + '" class="small muted">Kept with the finding\'s history.</p>' +
          '<button type="submit" class="btn">Approve (prototype, not sent)</button><div class="msg" role="status" aria-live="polite"></div></form>';
      } else {
        body += '<p class="small">You can see this proposal. Approving it needs the approver role and approve access to ' + esc(f.project || 'its project') + '. <span class="code">present: ' + esc(a.present.code) + '</span></p>';
      }
      return '<li class="entry" data-approval="' + esc(a.finding_id) + '"><details open><summary><span><span class="chev"></span><span class="title">' + esc(f.kind || a.finding_id) + '</span> ' + state +
        '<br><span class="meta">' + esc(f.subject) + ', ' + esc(f.project || 'builder-wide') + '</span></span><span class="r">' + amountText(f.amount) + '</span></summary><div class="body">' + body + '</div></details></li>';
    }).join('') + '</ul>';
    return out;
  }
  function onApprove(form) {
    var a = V.approvals[+form.getAttribute('data-i')], t = form.querySelector('textarea'), msg = form.querySelector('.msg');
    if (!t.value.trim()) { t.setAttribute('aria-invalid', 'true'); msg.innerHTML = '<p class="status-msg">Write why you approve it first. The approval boundary refuses a request without a rationale.</p>'; t.focus(); return; }
    t.removeAttribute('aria-invalid');
    var rq = { request_id: 'chosen by the screen, one per intended approval', finding_id: a.finding_id, version: a.request.version, digest: a.request.digest, proposal: a.request.proposal, rationale: t.value.trim() };
    msg.innerHTML = '<div class="status-msg"><p><strong>Not sent.</strong> This is a prototype. The product would send this request once to request_approval, and the boundary would check it again:</p><pre class="small">' + esc(JSON.stringify(rq, null, 1)) + '</pre></div>';
  }

  /* ---------------------------------------------------------------- materials ---------------------------------------------------------------- */
  var SCN = { 'buy_now': 'Buy now', 'wait': 'Wait', 'wait:flat': 'Wait, price flat', 'wait:down_5pct': 'Wait, price 5% lower', 'wait:up_5pct': 'Wait, price 5% higher', 'wait:flat:flat': 'Wait, price flat', 'wait:down_5pct:down_5pct': 'Wait, price 5% lower', 'wait:up_5pct:up_5pct': 'Wait, price 5% higher', 'stage': 'Buy in stages', 'negotiate': 'Negotiate' };
  function materials() {
    var reqs = [];
    V.projects.forEach(function (p) { if (p.materials) p.materials.requirements.forEach(function (r) { reqs.push([p, r]); }); });
    var anyMkt = V.projects.some(function (p) { return p.materials; });
    if (!anyMkt) return '<h1>No market data has been received for this builder.</h1><p class="lede">Quotes, specifications and price indices arrive as their own files. Until they do, buy-timing cannot be assessed and nothing is suggested.</p>';
    var out = '<h1>Buy-timing for ' + reqs.length + (reqs.length === 1 ? ' requirement' : ' requirements') + '.</h1><p class="lede">Scenarios to compare, not recommendations. No quote is chosen and no saving is realised; every purchase decision needs a person. A scenario never changes the official forecast.</p>';
    reqs.forEach(function (pr) {
      var p = pr[0], r = pr[1];
      var offers = r.offers.map(function (o) { return '<tr><th scope="row">' + esc(o.offer) + (o.supplier ? '<div class="small muted">' + esc(o.supplier) + (o.specification ? ', ' + esc(o.specification) : '') + '</div>' : '') + '</th><td>' + esc(words(o.class)) + (o.reasons.length ? '<div class="small muted">' + esc(o.reasons.join('; ')) + '</div>' : '') + '</td><td class="small">' +
        o.freshness.map(function (x) { return esc(words(x.state)) + (x.age_days !== null && x.age_days !== undefined ? ', ' + x.age_days + ' days old (limit ' + x.threshold_days + ')' : '') + (x.valid_until ? ', valid until ' + esc(day(x.valid_until)) : ''); }).join('<br>') +
        '</td><td>' + (o.landed_complete ? 'Complete' : 'Incomplete') + '</td><td class="small">' + (o.blockers.length ? o.blockers.map(function (b) { return esc(b.plain || b.code) + ' <span class="code">' + esc(b.code) + '</span>'; }).join('<br>') : '<span class="muted">None</span>') + '</td></tr>'; }).join('');
      var excl = r.excluded.length ? '<p class="note prov">Excluded: ' + r.excluded.map(function (x) { return esc(x.offer) + ' (' + esc(words(x['class'])) + ': ' + esc(x.why.join('; ')) + ')'; }).join('; ') + '</p>' : '';
      var scn = r.scenarios.length ? '<div class="table-wrap"><table><thead><tr><th scope="col">Scenario</th><th scope="col">Offer</th><th scope="col">Status</th><th scope="col" class="r">Landed total</th><th scope="col" class="r">Extra costs</th><th scope="col">Gaps and limits</th></tr></thead><tbody>' +
        r.scenarios.map(function (s) {
          var gaps = (s.why ? [s.why] : []).concat(s.evidence_gaps || [], s.uncertainty || []);
          var tot = s.landed_total ? num(s.landed_total, (SCN[s.scenario] || s.scenario) + ', ' + (s.offer || '') + ', landed total') :
                    (s.potential_difference.length ? s.potential_difference.map(function (d) { return num(d, 'Possible difference, ' + s.scenario); }).join('<br>') + '<div class="small muted">possible difference</div>' : '<span class="muted">-</span>');
          return '<tr><th scope="row">' + esc(SCN[s.scenario] || words(s.scenario)) + '</th><td class="small">' + esc(s.offer || 'all offers') + '</td><td>' + (s.status === 'not_available' ? tag('Not available', 'waiting') : tag('Scenario only')) + '</td><td class="r">' + tot +
            '</td><td class="r">' + (s.incremental_total ? num(s.incremental_total, (SCN[s.scenario] || s.scenario) + ', extra costs') : '<span class="muted">-</span>') + '</td><td class="small">' + (gaps.length ? '<ul style="margin:0;padding-left:1.1em">' + gaps.map(function (g) { return '<li>' + esc(g) + '</li>'; }).join('') + '</ul>' : '') + '</td></tr>';
        }).join('') + '</tbody></table></div>' : '<p class="muted small">No scenarios: ' + esc(words(r.scenario_status || 'not run for this kind of requirement')) + '.</p>';
      out += '<section aria-labelledby="h-' + esc(r.requirement.replace(/[^A-Za-z0-9]/g, '')) + '"><header><h2 id="h-' + esc(r.requirement.replace(/[^A-Za-z0-9]/g, '')) + '">' + esc(r.material_name || r.material) + ' for ' + esc(p.name) + '</h2>' +
        '<span class="muted small">' + esc(r.requirement) + (r.required_date ? ', needed by ' + esc(day(r.required_date)) : '') + ', ranking ' + esc(r.ranking_status) + '</span></header>' +
        '<div class="table-wrap"><table><thead><tr><th scope="col">Offer</th><th scope="col">Comparable?</th><th scope="col">Freshness</th><th scope="col">Landed cost</th><th scope="col">Blocks a definitive ranking</th></tr></thead><tbody>' + offers + '</tbody></table></div>' + excl +
        (r.context && r.context.note ? '<p class="small muted">Price index: ' + esc(r.context.note) + '.</p>' : '') + '<h3 style="margin:16px 0 8px">Scenarios</h3>' + scn + '</section>';
    });
    var tm = V.tenant_materials;
    if (tm) {
      out += '<section aria-labelledby="h-fresh"><header><h2 id="h-fresh">How fresh the market evidence is</h2></header><div class="table-wrap"><table><thead><tr><th scope="col">Material</th><th scope="col">Price index</th><th scope="col">Quotes</th></tr></thead><tbody>' +
        tm.evidence_register.map(function (e) { return '<tr><th scope="row">' + esc(e.material) + '</th><td>' + esc(words(e.index_state)) + (e.index_age_days !== null && e.index_age_days !== undefined ? ', ' + e.index_age_days + ' days old (limit ' + e.index_threshold_days + ')' : '') + '</td><td class="small">' +
          (e.quotes.length ? e.quotes.map(function (q) { return esc(q.subject) + ': ' + esc(words(q.state)); }).join('<br>') : '<span class="muted">None</span>') + '</td></tr>'; }).join('') + '</tbody></table></div></section>';
      if (tm.duplicates.length) out += '<section aria-labelledby="h-dup"><header><h2 id="h-dup">Possible duplicate orders</h2></header><ul>' + tm.duplicates.map(function (d) {
        return '<li>' + esc(d.project) + ', ' + esc(d.material) + ', ' + esc(d.supplier) + ': ' + d.orders.map(function (o) { return esc(o.ref) + ' ' + num(o.amount, o.ref); }).join(' and ') + (d.held_as_candidates ? ' (held as candidates for a person to check)' : '') + '</li>'; }).join('') + '</ul></section>';
    }
    return out;
  }

  /* ---------------------------------------------------------------- the evidence drawer ---------------------------------------------------------------- */
  function kv(o) {
    var ks = Object.keys(o || {}).sort();
    if (!ks.length) return '<p class="muted">None.</p>';
    return '<div class="table-wrap"><table><tbody>' + ks.map(function (k) { var v = o[k]; return '<tr><th scope="row" class="small">' + esc(k) + '</th><td class="small">' + esc(typeof v === 'object' ? JSON.stringify(v) : v) + '</td></tr>'; }).join('') + '</tbody></table></div>';
  }
  function listRows(rows, cols) {
    if (!rows || !rows.length) return '<p class="muted small">None.</p>';
    return '<div class="table-wrap"><table><thead><tr>' + cols.map(function (c) { return '<th scope="col">' + esc(c[1]) + '</th>'; }).join('') + '</tr></thead><tbody>' +
      rows.map(function (r) { return '<tr>' + cols.map(function (c) { var v = r[c[0]]; if (c[2] === 'money' && typeof v === 'number') v = exact(v); else if (typeof v === 'object') v = JSON.stringify(v); return '<td class="small' + (c[2] === 'money' ? ' r' : '') + '">' + esc(v) + '</td>'; }).join('') + '</tr>'; }).join('') + '</tbody></table></div>';
  }
  function drawEvidence(id) {
    var e = V.evidence[id];
    if (!e) return;
    var body = '', kind = { calculation: 'APG calculation', record: 'Source record', finding: 'Finding', recommendation: 'Recommendation', scenario: 'Procurement scenario', import: 'Import receipt',
                            quality: 'Record outcomes', quarantine: 'Held value', portfolio: 'Detection portfolio view' }[e.type] || e.type;
    if (e.type === 'calculation') {
      body += '<p class="exact">' + (e.cents === null || e.cents === undefined ? 'No value: ' + esc(STATE_WORDS[e.state]) : esc(exact(e.cents))) + '</p><p>' + tag(STATE_WORDS[e.state] || e.state) + ' as of ' + esc(day(e.as_of)) + '</p>' +
        (e.reasons && e.reasons.length ? '<h3>Reasons APG gave</h3>' + reasons(e.reasons) : '') + '<h3>How it was worked out</h3><pre>' + esc((e.explain || []).join('\n')) + '</pre>' +
        (e.unknown_inputs && e.unknown_inputs.length ? '<h3>Inputs it could not use</h3>' + listRows(e.unknown_inputs, [['input', 'Input'], ['reason', 'Reason'], ['decision', 'Detail']]) : '') +
        (e.excluded && e.excluded.length ? '<h3>Records left out</h3>' + listRows(e.excluded, [['ref', 'Record'], ['class', 'Why'], ['codes', 'Codes'], ['amount_cents', 'Amount', 'money']]) : '') +
        (e.contributed && e.contributed.length ? '<h3>Largest records it used</h3>' + listRows(e.contributed, [['ref', 'Record'], ['revision', 'Revision'], ['role', 'Role'], ['amount_cents', 'Amount', 'money']]) : '') +
        (e.by_cost_code ? '<h3>By cost code</h3>' + listRows(Object.keys(e.by_cost_code).sort().map(function (k) { var x = e.by_cost_code[k]; return { code: k, method: x.method, cents: x.cents }; }), [['code', 'Cost code'], ['method', 'Method'], ['cents', 'Amount', 'money']]) : '') +
        '<h3>Reproducibility</h3><dl class="req"><dt>Formula</dt><dd>' + esc(e.formula) + (e.formula_version ? ' v' + esc(e.formula_version) : '') + '</dd><dt>Run key</dt><dd class="code">' + esc(e.run_key) + '</dd>' +
        (e.inputs_pinned !== undefined ? '<dt>Inputs pinned</dt><dd>' + esc(e.inputs_pinned) + ' records, each at an exact revision</dd>' : '') + (e.policy ? '<dt>Policy</dt><dd>' + esc(e.policy.version) + (e.policy.approved ? ', approved' : ', not approved') + ' (illustrative)</dd>' : '') + '</dl>';
    } else if (e.type === 'record') {
      body += '<p>' + (e.found ? 'Revision ' + esc(e.revision) + (e.role ? ', used as ' + esc(e.role) : '') + (e.outcome ? ', ' + esc(words(e.outcome)) : '') + (e.source_file ? ', from ' + esc(e.source_file) : '') : 'Not found in this tenant\'s records.') + '</p>' + kv(e.fields);
    } else if (e.type === 'finding') {
      var q = e.quantification || {};
      body += '<p>' + tag(words(e.status)) + ' version ' + esc(e.version) + ', rule ' + esc(e.rule) + '</p><dl class="req"><dt>Observed</dt><dd>' + esc((e.explanation || {}).observed) + '</dd><dt>Expected</dt><dd>' + esc((e.explanation || {}).expected) + '</dd>' +
        '<dt>Amount</dt><dd>' + (q.status === 'quantified' ? esc(exact(q.gross_cents)) + ' (' + esc(LABEL_WORDS[q.label] || q.label) + ')' : 'not quantified') + '</dd><dt>Basis</dt><dd>' + esc(q.basis || '') + '</dd>' +
        (q.calculation_ref ? '<dt>Calculation</dt><dd class="code">' + esc(q.calculation_ref) + '</dd>' : '') + '<dt>State digest</dt><dd class="code">' + esc(e.state_digest) + '</dd></dl>' +
        '<h3>Source records</h3><ul>' + (e.records || []).map(function (r) { return '<li><button type="button" class="num" data-ev="' + esc(r) + '">' + esc(r.replace('E-rec-', '')) + '</button></li>'; }).join('') + '</ul>' +
        '<h3>History</h3>' + listRows(e.history, [['at', 'When'], ['actor', 'Who'], ['event', 'What'], ['to', 'Status']]);
    } else if (e.type === 'recommendation') {
      var x = e.explanation || {};
      body += '<p>' + tag(ROUTE_WORDS[e.route] || e.route) + (e.category ? ' ' + esc(words(e.category)) : '') + '</p><dl class="req"><dt>Potential gross</dt><dd>' + (e.magnitude && e.magnitude.cents !== null && e.magnitude.cents !== undefined ? esc(exact(e.magnitude.cents)) + ': ' + esc(e.magnitude.kind) : 'not quantified') + '</dd>' +
        '<dt>Estimated net</dt><dd>' + (e.net_benefit && e.net_benefit.status === 'estimated' ? esc(exact(e.net_benefit.cents)) + ', an estimate (' + esc(e.net_benefit.formula) + ')' : 'not estimated') + '</dd></dl>' +
        ['what_and_why_now', 'benefits_costs_tradeoffs', 'evidence_and_uncertainty', 'required_approval', 'outcome_measurement', 'not_a_claim'].filter(function (k) { return x[k]; }).map(function (k) { return '<h3>' + esc(words(k.replace(/_and_/g, ' and '))) + '</h3><p>' + esc(x[k]) + '</p>'; }).join('');
    } else if (e.type === 'scenario') {
      var s = e.scenario || {};
      body += '<p>' + tag(words(s.status)) + ' Changes the official forecast: ' + (s.changes_authoritative_forecast ? 'yes' : 'no') + '. Needs a person to decide: ' + (s.human_approval_required ? 'yes' : 'no') + '.</p>' +
        (s.landed_total_cents !== undefined && s.landed_total_cents !== null ? '<p class="exact">' + esc(exact(s.landed_total_cents)) + ' landed</p>' : '') + (s.why ? '<p>' + esc(s.why) + '</p>' : '') +
        '<h3>Assumptions</h3><ul>' + (s.assumptions || []).map(function (a) { return '<li>' + esc(a) + '</li>'; }).join('') + '</ul>' +
        '<h3>Extra costs</h3>' + listRows(s.incremental_costs, [['label', 'Cost'], ['basis', 'Basis'], ['cents', 'Amount', 'money']]) +
        '<h3>Evidence gaps</h3><ul>' + (s.evidence_gaps || []).concat(s.uncertainty || []).map(function (a) { return '<li>' + esc(a) + '</li>'; }).join('') + '</ul><p class="small muted">' + esc(e.statement) + '</p><p class="code">run ' + esc(e.run_key) + '</p>';
    } else if (e.type === 'import') {
      body += '<p>' + esc(words(e.status)) + ' on ' + esc(day(e.received_at)) + ' from ' + esc(words(e.source)) + '</p><dl class="req"><dt>File SHA-256</dt><dd class="code">' + esc(e.file_sha256) + '</dd></dl><h3>Counts</h3>' + kv(e.counts) +
        '<h3>Rows not simply accepted</h3>' + listRows(e.not_accepted, [['row', 'Row'], ['key', 'Record'], ['result', 'Result'], ['detail', 'Detail']]);
    } else if (e.type === 'portfolio') {
      body += '<p>' + esc((e.view || {}).range_display) + '</p><p class="small">' + esc((e.view || {}).note) + '</p>' + kv(e.view);
    } else {
      body += kv(e.counts || e.item || e);
    }
    var root = document.getElementById('drawer-root');
    lastFocus = document.activeElement;
    root.innerHTML = '<div class="scrim" data-close="1"></div><aside class="drawer" role="dialog" aria-modal="true" aria-labelledby="ev-title" data-ev-open="' + esc(id) + '"><header><div><span class="kind">' + esc(kind) + '</span><h2 id="ev-title" tabindex="-1">' + esc(e.title) + '</h2></div>' +
      '<button type="button" class="btn ghost" data-close="1">Close</button></header><div class="content">' + body + '</div></aside>';
    document.getElementById('ev-title').focus();
  }
  function closeDrawer() {
    var root = document.getElementById('drawer-root');
    if (!root.innerHTML) return;
    root.innerHTML = '';
    if (lastFocus && document.body.contains(lastFocus)) lastFocus.focus();
  }

  document.addEventListener('click', function (ev) {
    var sk = ev.target.closest ? ev.target.closest('a.skip') : null;
    if (sk) { ev.preventDefault(); document.getElementById('main').focus(); return; }
    var t = ev.target.closest ? ev.target.closest('[data-ev],[data-close]') : null;
    if (!t) return;
    if (t.hasAttribute('data-close')) { closeDrawer(); return; }
    ev.preventDefault();
    drawEvidence(t.getAttribute('data-ev'));
  });
  document.addEventListener('submit', function (ev) { if (ev.target.classList.contains('approve')) { ev.preventDefault(); onApprove(ev.target); } });
  document.addEventListener('keydown', function (ev) {
    var d = document.querySelector('.drawer');
    if (!d) return;
    if (ev.key === 'Escape') { ev.preventDefault(); closeDrawer(); return; }
    if (ev.key === 'Tab') {
      var f = d.querySelectorAll('button, [href], [tabindex]:not([tabindex="-1"]), select, textarea');
      if (!f.length) return;
      var first = f[0], last = f[f.length - 1];
      if (ev.shiftKey && (document.activeElement === first || document.activeElement.id === 'ev-title')) { ev.preventDefault(); last.focus(); }
      else if (!ev.shiftKey && document.activeElement === last) { ev.preventDefault(); first.focus(); }
    }
  });
  window.addEventListener('hashchange', function () { closeDrawer(); render(); var m = document.getElementById('main'); if (m) m.focus({ preventScroll: true }); window.scrollTo(0, 0); });
  try { var th = localStorage.getItem('apg-theme'); if (th) document.documentElement.setAttribute('data-theme', th); } catch (e) {}
  render();
})();
